parameters.functionCode:
const raw = $json.output_text || $json.output?.[0]?.content?.[0]?.text || '';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { throw new Error('Keywords JSON invalide: ' + raw); }
const keywords = Array.isArray(parsed.keywords) ? parsed.keywords : [];
const limit = Number($node['Set Config'].json.keywordCount || 8);
const itemsOut = keywords
  .map((k) => String(k || '').trim())
  .filter((k) => !!k)
  .slice(0, limit)
  .map((keyword) => ({ json: { keyword } }));
if (!itemsOut.length) { throw new Error('Aucun keyword genere.'); }
return itemsOut;

const out = [];
const maxBatch = Number($node['Set Config'].json.maxCandidates || 20);
for (const item of items) {
  const results = Array.isArray(item.json.results) ? item.json.results : [];
  for (const hit of results) {
    const imageUrl = hit.url || hit.thumbnail;
    if (!imageUrl) continue;
    out.push({ json: { image_url: imageUrl } });
    if (out.length >= maxBatch) break;
  }
  if (out.length >= maxBatch) break;
}
if (!out.length) { throw new Error('Aucune image recuperee depuis Openverse.'); }
return out;

parameters.jsonBody:
={{ {
  model: 'gpt-4.1-mini',
  input: [
    { role: 'system', content: 'You return strict JSON only.' },
    {
      role: 'user',
      content: [
        {
          type: 'input_text',
          text: 'Analyze this food image and return STRICT JSON only with schema: {\"source_keyword\": string|null, \"image_url\": string, \"dish_name\": string, \"servings\": number, \"notes\": string, \"recipe\": {\"name\": string, \"servings\": number, \"ingredients\": string[], \"steps\": string[]}}. Keep servings=2 by default and keep image_url exactly as provided.'
        },
        { type: 'input_text', text: 'Provided image_url: ' + $json.image_url },
        { type: 'input_image', image_url: $json.image_url }
      ]
    }
  ]
} }}

parameters.functionCode:
const candidates = [];
for (const item of items) {
  const raw = item.json.output_text || item.json.output?.[0]?.content?.[0]?.text || '';
  let parsed;
  try { parsed = JSON.parse(raw); } catch (e) { continue; }
  const dishName = String(parsed.dish_name || '').trim();
  const imageUrl = String(parsed.image_url || '').trim();
  if (!dishName || !imageUrl) continue;
  candidates.push({
    source_keyword: parsed.source_keyword || null,
    dish_name: dishName,
    servings: Number(parsed.servings || 2),
    image_url: imageUrl,
    notes: parsed.notes || '',
    recipe: parsed.recipe || null,
    auto_approve: true
  });
}
if (!candidates.length) { throw new Error('Aucun candidat valide parse depuis agent vision.'); }
return [{ json: { candidates } }];

